public class Thermostat
{
    public event EventHandler<int>? TemperatureChanged;   // outside: += and -= only
    public Action<int>? RawCallback;                      // outside: anything goes

    public void Set(int value)
    {
        OnTemperatureChanged(value);
        RawCallback?.Invoke(value);
    }

    protected virtual void OnTemperatureChanged(int value)
        => TemperatureChanged?.Invoke(this, value);
}

