public sealed class PriceFeed                    // long-lived (for example, a singleton)
{
    public event EventHandler<decimal>? PriceChanged;
    public void Publish(decimal p) => PriceChanged?.Invoke(this, p);
}

public sealed class PriceWidget : IDisposable   // short-lived
{
    private readonly PriceFeed _feed;
    public PriceWidget(PriceFeed feed)
    {
        _feed = feed;
        _feed.PriceChanged += OnPriceChanged;   // feed now references this widget
    }

    private void OnPriceChanged(object? sender, decimal price) => Console.WriteLine(price);

    public void Dispose() => _feed.PriceChanged -= OnPriceChanged;   // breaks the reference
}

