    {
        { IsVip: true }                       => 0m,
        { Country: "IN", Total: >= 500m }     => 0m,
        { Country: "IN" }                     => 40m,
        { Total: > 1000m and <= 5000m }       => 15m,
        _                                     => 25m,
    };

    public static string Describe(int[] values) => values switch
    {
