}

public abstract record LookupResult
{
    private LookupResult() { }                       // nested cases can call it; outside code can't
    public sealed record Found(string Name) : LookupResult;
    public sealed record NotFound : LookupResult;
    public sealed record Invalid(string Reason) : LookupResult;
}

public static class Api
{
    public static int ToStatusCode(LookupResult result) => result switch
    {
        LookupResult.Found            => 200,
        LookupResult.NotFound         => 404,
        LookupResult.Invalid          => 400,
        _ => throw new ArgumentOutOfRangeException(nameof(result)),  // still needed before C# 15
    };
}

