using System.Net;

async Task<string?> GetProfileAsync(HttpClient http, string id)
{
    try
    {
        return await http.GetStringAsync($"/profiles/{id}");
    }
    catch (HttpRequestException ex) when (ex.StatusCode == HttpStatusCode.NotFound)
    {
        return null;                               // only 404 is handled here
    }
    catch (Exception ex) when (LogAndContinue(ex))
    {
        throw;                                     // never reached: the filter returns false
    }
}

static bool LogAndContinue(Exception ex)
{
    Console.Error.WriteLine(ex.Message);
    return false;                                  // don't handle; let it propagate unchanged
}

